  ComboBox MacroCombo(double width){var combo=new ComboBox{MinWidth=width,Foreground=text,Background=Brushes.Transparent,BorderBrush=muted,Padding=new Thickness(8,4,8,4),Margin=new Thickness(0,0,0,12),FontSize=12};combo.Template=(ControlTemplate)System.Windows.Markup.XamlReader.Parse("<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='{x:Type ComboBox}'><Grid><ToggleButton Focusable='False' IsChecked='{Binding IsDropDownOpen, RelativeSource={RelativeSource TemplatedParent}, Mode=TwoWay}'><ToggleButton.Template><ControlTemplate TargetType='ToggleButton'><Border BorderBrush='#AAAAAA' BorderThickness='0.7' CornerRadius='3' Background='#101010'/></ControlTemplate></ToggleButton.Template></ToggleButton><ContentPresenter Margin='10,3,30,3' Content='{TemplateBinding SelectionBoxItem}' ContentTemplate='{TemplateBinding ItemTemplate}' ContentStringFormat='{TemplateBinding SelectionBoxItemStringFormat}' IsHitTestVisible='False' VerticalAlignment='Center'/><Path Data='M 0,0 L 8,0 4,5 Z' Fill='#F1F1F1' Width='8' Height='5' HorizontalAlignment='Right' VerticalAlignment='Center' Margin='0,0,10,0' IsHitTestVisible='False'/><Popup IsOpen='{TemplateBinding IsDropDownOpen}' Placement='Bottom' AllowsTransparency='True' Focusable='False' PopupAnimation='None'><Border Background='#1C1C1C' BorderBrush='#AAAAAA' BorderThickness='0.7' MinWidth='{Binding ActualWidth, RelativeSource={RelativeSource TemplatedParent}}'><ScrollViewer MaxHeight='280'><ItemsPresenter/></ScrollViewer></Border></Popup></Grid></ControlTemplate>");var style=new Style(typeof(ComboBoxItem));style.Setters.Add(new Setter(Control.ForegroundProperty,text));style.Setters.Add(new Setter(Control.BackgroundProperty,panel));style.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(8,5,8,5)));var selected=new Trigger{Property=ComboBoxItem.IsHighlightedProperty,Value=true};selected.Setters.Add(new Setter(Control.BackgroundProperty,Brush("#34302A")));style.Triggers.Add(selected);combo.ItemContainerStyle=style;return combo;}
