  Grid MacroEmptyParameters(){var area=new Grid{Height=500,Width=265,Tag="Macro.EmptyParameters"};var empty=new StackPanel{VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center,RenderTransform=new TranslateTransform(0,18)};var icon=new Canvas{Width=72,Height=72,Margin=new Thickness(12,0,0,0),HorizontalAlignment=HorizontalAlignment.Center};icon.Children.Add(new System.Windows.Shapes.Polygon{Points=new PointCollection(new[]{new Point(5,19),new Point(19,5),new Point(67,5),new Point(67,52),new Point(53,67),new Point(5,67)}),Stroke=text,StrokeThickness=3,Fill=Brushes.Transparent});icon.Children.Add(new System.Windows.Shapes.Path{Data=Geometry.Parse("M 24,50 L 24,29 36,38 49,29 49,50"),Stroke=text,StrokeThickness=5});empty.Children.Add(icon);var prompt=Label("请选择一个项目以调整参数。",14,text,FontWeights.SemiBold);prompt.Margin=new Thickness(0,26,0,0);prompt.TextAlignment=TextAlignment.Center;empty.Children.Add(prompt);area.Children.Add(empty);return area;}
  ContextMenu BuildMacroOptionsMenu(){var menu=new ContextMenu{Background=panel,Foreground=text};var run=new MenuItem{Header="软件执行",IsEnabled=!render&&!MacroFeaturesActive&&macroEditor.Current.Actions.Count>0,ToolTip="3 秒倒计时后向前台窗口执行 · F9 / 停止可取消"};run.Click+=(s,e)=>BeginMacroPlayback();menu.Items.Add(run);var stop=new MenuItem{Header="停止",IsEnabled=MacroFeaturesActive};stop.Click+=(s,e)=>StopMacroFeatures();menu.Items.Add(stop);menu.Items.Add(new Separator());var positions=new MenuItem{Header="录制鼠标移动",IsCheckable=true,IsChecked=macroPositions,IsEnabled=!MacroFeaturesActive};positions.Checked+=(s,e)=>macroPositions=true;positions.Unchecked+=(s,e)=>macroPositions=false;menu.Items.Add(positions);foreach(string action in new[]{"上移","下移","删除"}){string command=action;var item=new MenuItem{Header=command,IsEnabled=!MacroFeaturesActive&&macroSelection>=0&&macroSelection<macroEditor.Current.Actions.Count};item.Click+=(s,e)=>MoveMacroAction(command);menu.Items.Add(item);}return menu;}
